Copy the workbook, build a first-of-month date for each I–T column from the month/year headers, then scan each item row right-to-left for the last positive quantity and write that date into U9:U18.

```python
import shutil
import datetime
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals["Data"]
ws = wb["Data"]

month_map = {
    "january": 1, "jan": 1,
    "february": 2, "feb": 2,
    "march": 3, "mar": 3,
    "april": 4, "apr": 4,
    "may": 5,
    "june": 6, "jun": 6,
    "july": 7, "jul": 7,
    "august": 8, "aug": 8,
    "september": 9, "sep": 9, "sept": 9,
    "october": 10, "oct": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}

cols = list(range(9, 21))  # I to T
col_date = {}
current_year = None
prev_month = None

for c in cols:
    m = vws.cell(row=7, column=c).value
    y = vws.cell(row=6, column=c).value

    month = month_map.get(str(m).strip().lower()) if m is not None else None

    explicit_year = None
    if y is not None and str(y).strip():
        try:
            explicit_year = int(float(str(y).strip()))
        except Exception:
            explicit_year = None

    wrap = False
    if month is None:
        if prev_month is None:
            month = 1
        else:
            month = prev_month + 1
            if month > 12:
                month = 1
                wrap = True
    else:
        wrap = (prev_month == 12 and month == 1)

    if explicit_year is not None:
        current_year = explicit_year
    else:
        if current_year is None:
            current_year = 2015 if month >= 6 else 2016
        elif wrap:
            current_year += 1

    col_date[c] = datetime.date(current_year, month, 1)
    prev_month = month

def is_positive_number(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return v > 0
    try:
        return float(str(v).strip().replace(",", "")) > 0
    except Exception:
        return False

for r in range(9, 19):
    last = None
    for c in cols:
        if is_positive_number(vws.cell(row=r, column=c).value):
            last = col_date[c]

    cell = ws.cell(row=r, column=21)  # U
    cell.value = last
    cell.number_format = "m/d/yyyy"
    print(r, last)

wb.save(OUT)
